
/*CBJS-START*/
/* ============================================================
   コンボ集（技チェックシートと同じページの中で切り替える画面）
   ------------------------------------------------------------
   ■ あらかじめ載せるコンボのデータ（キャラごと）。キャラのid（技チェックシートと同じ）をキーにして、配列を入れます。
     COMBOS.alisa = [
       { k: 1, g: "浮かせ", n: "3RP 始動", c: "3RP＞9LP(T)＞66～9LP", d: 75, lv: 2, t: ["壁"], note: "備考" },
     ];
     k    : コンボの固定ID（整数）。メモ・編集・並び順・書き出しコードは「キャラid＋k」で管理します。
            追加するときは、そのキャラの「いちばん大きいk＋1」を付けてください。一度付けたkは変更・再利用しない。
     g    : 分類（見出し）。例：浮かせ／崩し／壁／ヒート／レイジ　　　　（省略可）
     n    : コンボ名・始動技                                                  （省略可）
     c    : コマンド。LP RP LK RK WP WK … （左の2つ=LP+LK／右の2つ=RP+RK と書く。WL・WR は使わない）／ 数字は方向（6=前 4=後ろ 2=下 8=上 1・3・7・9=斜め 5=ニュートラル、
            6^ のように ^ を付けるとホールド）／ ＞ は次の入力へ／ (T) はトルネード誘発／強k は強きりもみ／前ダッシュ は前ダッシュ／立ち途中 は立ち途中／HB はヒートバースト／ジャスト・ホールド（カプセル型のタグ。方向を長押しする 6^ とは別）／左横移動・右横移動・左横歩き・右横歩き・微歩き・バックステップ など。アイコンに自動で置き換わります。
     d    : ダメージ（数値でも "75(39)" のような文字でも可）                       （省略可）
     lv   : 難易度 1〜5                                                        （省略可）
     t    : 条件のタグの配列。例：["壁","ヒート","レイジ","トルネード","カウンター"]  （省略可）
            「カウンター」が付いて「通常ヒット」が付かないコンボは、カウンターヒット時限定のコンボ。確定反撃表からのジャンプの対象にならない
            （その技から始まるコンボが、現バージョンですべてカウンターヒット時限定なら、その技には確定反撃表のリンクを作らない）
     note : 備考                                                              （省略可）
   ■ 動画つきのコンボ（mp4）：現在、付属の mp4 の動画は 0 本です（アーマーキング No.59 は YouTube に切り替えて、mp4 の元データは削除した。2026-10-28）。仕組みは残してあり、動画（mp4）は、下の COMBO_VIDEOS（combo_videos.js。mk_combo_videos.py で作る）に入れます。{ cid: キャラid, k: コンボのk, n: 始動技の名前, c: コマンド, mime, b64: 動画のbase64 }
     { cid, k（付属コンボに付けるときだけ）, n: 始動技の名前, names: 始動技の別名の配列（省略可）, d: ダメージ, c: コマンド, mime, b64 }。指定した1つのコンボだけに付きます（自作・書き換え・付属のどれでも可。付き方は、下の「動画つきのコンボ」の説明）。
     動画のあるコンボは、メモの上に「動画を再生」ボタンが出て、確定反撃表のジャンプリンクと同じ色の枠（--accent）で囲まれます。
   ■ YouTube の動画：コンボの yt（省略可）に、YouTube に投稿した動画のURLを入れると（編集画面の「動画（YouTubeのURL）」欄でも入れられる）、そのコンボに「動画を再生」が付きます。
     押すとカードの中に小さなプレーヤー（ミニウィンドウ）が開き、「拡大」で、ギャラリーの画像の拡大と同じ作りの拡大表示（外側に余白を残す）になります。保存は「https://youtu.be/動画ID」の形（開始位置は「?t=秒」）。
     書き換え・自作・公開データ・書き出しコードに、そのまま入ります。付属の mp4 の動画（COMBO_VIDEOS）が同じコンボに付くときは、YouTube のほうを使います。
   ■ 書き換え済みの目印：付属のコンボを「編集」で書き換えて保存していると（分類を別の分類へ動かしたときも同じ）、そのコンボに「書き換え済み」と出ます。書き換えたコンボは、付属データが新しくなっても、書き換えた内容のままです。
     一覧の上の「書き換えた N件を元の内容に戻す」で、そのキャラの書き換えを全部外して、付属データの最新の内容に戻せます（確認のあと。画面下の「元に戻す」で取り消せます）。
   ■ 保存データの内訳：「書き出し・読み込み」の画面の下に、このブラウザに保存されているコンボのデータ（書き換え・自作・削除・並び順・分類の並び・メモ）の件数が出ます。何も無いときは、ファイルに入っている付属データそのままの表示です。
     「保存データをすべて消す」で、全キャラ分を消して付属データそのままの表示に戻せます（確認のあと。画面下の「元に戻す」で取り消せます）。
   ■ 通し番号：一覧の各コンボには、上から順の番号（No.）が付きます。並べ替え・追加・削除・分類の入れ替えで、番号も付け直されます（検索・絞り込み中も、全体の番号のまま）。
   ■ 動画つきコンボへのジャンプ：動画のあるコンボが1件でもあるキャラでは、一覧の上に「動画つきのコンボ」の帯が出ます。コンボごとのリンク（No.・名前・ダメージ）を押すと、そのコンボへ飛びます
     （閉じている分類は開き、検索・絞り込みで隠れているときは解除して出す）。「次の動画へ」は、押すたびに次の動画つきコンボへ順に飛びます（最後のあとは最初へ）。
   ■ 消せる表示：「書き換えた N件を元の内容に戻す」ボタンと、各コンボの「書き換え済み」の目印には「×」が付いていて、押すと消えます（画面下の「元に戻す」で取り消せる）。
     「書き出し・読み込み」の画面の「表示の設定」で、いつでも出し直せます。設定は tekken-combo-ui-v1（{ noEdTag, noEdBtn }。初期値のままのものは入れない）。
   ■ 分類の名前の変更：分類（見出し）の右の「✏️」で、その分類の名前を変えられます（そのキャラの、その分類のコンボ全部。すでにある分類の名前にすると、1つにまとまる）。
     付属データは変えず、「もとの名前 → いまの名前」の対応（tekken-combo-grename-v1）を重ねて見せるだけなので、付属コンボは「書き換え済み」になりません。「分類の名前の変更を元に戻す」で全部戻せます。
   ■ 分類を編集（専用の画面）：「＋ コンボを追加」の右の「分類を編集」で開きます。分類の名前を変える（✏️）・消す（✖。使っているコンボは「その他」へ）・追加する、と、コンボを「選択して削除」でまとめて消すことができます。
     上の切り替えで、「このキャラだけ」か「全キャラ共通」を選べます。全キャラ共通では、名前を変える・消すが、その分類を使っている全キャラに効きます（追加は、もともと全キャラ共通の分類のリストに足します）。コンボの選択削除は、このキャラだけです。
     この画面を開いている間は、画面下の「元に戻す」の通知が隠れるため、直前の操作は、画面内の「直前の操作を元に戻す」で取り消します。
   ■ 分類のプルダウン（編集画面）：右の「✖」で選んでいる分類を消し、「✏️」で名前を変えられます。使っている分類を消すときは、そのコンボを「その他」（分類なし）に移します（確認あり）。
     決まった例（GROUP_PRESETS）や、「＋ 新しい分類を入力…」から「リストに追加」した名前は、tekken-combo-glist-v1（{ add, hide }）に残ります。
   ■ 新しいビルドを開いたとき：付属コンボの書き換え・削除・並び順・分類の並びは、捨てずにそのまま引き継ぎます。ただし、付属データ側（ファイルに入っている内容・公開データ）が更新されたコンボだけは、
     そのコンボの書き換えを外して、新しい内容を出します。付属コンボ1件ごとの中身の指紋を tekken-combo-basefp-v1 に記録しておき、開いたとき・公開データを取り入れたときに、記録と比べます。
     書き換えが新しい内容と同じになっていれば外すだけ。付属データから無くなったコンボの書き換え・削除の記録も外します（削除は、内容が変わっただけなら削除したまま）。記録が無い最初の1回は、記録するだけで何も外しません。
     自作コンボ・メモ・分類の名前の変更・表示の設定には触れません。
   ■ 控え：外した書き換えは「控え」（tekken-combo-backups-v1。最大5世代、新しい順）に残り、画面下の「元に戻す」と、「書き出し・読み込み」の「控え」の「戻す」で、いまの内容へ足し戻せます（同じコンボは、控えの書き換えが優先）。
     「戻す前の内容」も新しい控えとして残します（今の内容は消えません。「戻す前の内容」を戻すと、その時点の内容に入れ替わります）。同じ内容の控えは重ねません。
     6件目からは、いちばん古い控えから外します。「消す」で1件ずつ、「控えをすべて消す」で全部消せます（確認のあと。消した控えは戻せません）。
   ■ 「〇〇を元に戻す」の約束：「〇〇を元に戻す」というボタン（並び順・分類の並び・分類の名前の変更・削除したコンボ）を新しく足すときは、必ず「変更を確定」（元に戻す項目を消す）にも、その項目を消す（確定する）働きを足す。
     分類の名前の変更は、確定すると「分類の名前の変更を元に戻す」が出なくなります（名前は変わったまま。tekken-combo-grenameok-v1 に確定した状態を記録し、またその分類の名前を変えると、ボタンがまた出ます）。
   ■ 付属データへの組み込み：組み込んだ自作コンボは、COMBOS_BAKED（{ キャラid: { 自作のid: k } }）に記録し、ブラウザに残っている同じ自作コンボは、開いたときに外します（そのメモは付属コンボのメモへ移します）。
   画面の「＋ コンボを追加」で登録したコンボは、このデータとは別にブラウザへ保存されます。
   画面の「編集」で書き換えた内容（付属・自作どちらも）もブラウザへ保存します。付属のコンボは、このデータ自体は変わらず、書き換え分を上から重ねる形です（「元の内容に戻す」で外せます）。
   ============================================================ */
