    if (kept) { try { localStorage.setItem(BAK_KEY, JSON.stringify([kept].concat(list))); } catch (_) { return null; } }       // 先に、いまの内容を控えへ（入らなければ何もしない）
    try { LAYER_KEYS.forEach(k => { if (next[k] != null) localStorage.setItem(k, next[k]); else localStorage.removeItem(k); }); }
    catch (_) { try { LAYER_KEYS.forEach(k => { if (cur && cur[k] != null) localStorage.setItem(k, cur[k]); else localStorage.removeItem(k); }); } catch (_) {} return null; }
