    if (catRows().some(([g]) => g === v)) { catMsg("「" + v + "」という分類は、すでにあります。", true); $("catNewIn").focus(); return; }
    const snap = snapG();
    if (!GROUP_PRESETS.includes(v) && !glist.add.includes(v)) glist.add.push(v);
    glist.hide = glist.hide.filter(x => x !== v);
    saveGlist(); $("catNewIn").value = ""; catRender();
    catMsg("分類「" + v + "」を追加しました（全キャラのコンボ編集の分類リストに出ます）。");
