      if (orig && same(f) === same(orig)) {
        if (edits[cid]) { delete edits[cid][id]; if (!Object.keys(edits[cid]).length) delete edits[cid]; }
      } else (edits[cid] = edits[cid] || {})[id] = storeFields(cid, f);
