    const arr = userCombos[current] = userCombos[current] || [];
    if (editing) { const i = arr.findIndex(x => x.id === editing.id); if (i >= 0) arr[i] = o; else arr.push(o); } else arr.push(o);
    saveUser(); closeDlg(edDlg); renderAll();
